{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Randomized controlled trials were eligible for efficacy synthesis when they enrolled participants undergoing outpatient or office-based blind endometrial biopsy or endometrial sampling and reported pain, tolerability, additional analgesia, satisfaction, or adverse-event outcomes. No restrictions were placed on publication year, language, country, indication for biopsy, menopausal status, or biopsy device, provided that the target procedure was blind endometrial biopsy or sampling and the relevant pain outcome was separable.",
      "reason": "Specifies study characteristics including design, setting, and outcomes."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "No restrictions were placed on publication year, language, country, indication for biopsy, menopausal status, or biopsy device, provided that the target procedure was blind endometrial biopsy or sampling and the relevant pain outcome was separable. Conference abstracts, registry entries, and secondary reports were retained for citation mapping and publication-bias assessment when they described potentially eligible trials, but they entered quantitative synthesis only when sufficient arm-level outcome data were available.",
      "reason": "Specifies eligibility criteria for report characteristics including year, language, and publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence found explicitly distinguishing exclusion based on outcomes not measured versus not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "To avoid mixing clinically different comparisons, we organized the evidence into three tiers. Tier 1 was the prespecified primary meta-analysis. It included inert-controlled randomized comparisons with extractable intra-procedural means and standard deviations. Tier 2 comprised sensitivity analyses that tested analytic or clinical boundaries. These included balanced-background ibuprofen designs, in which both randomized groups received ibuprofen and the randomized contrast assessed the added topical or local intervention. Tier 2 also included the analysis excluding the single systemic-only COX-2 inhibitor trial. Tier 3 comprised narrative or tabulated contextual evidence. This tier included medianonly, binary-only, ordinal-only, active-comparator, nonpharmacologic, cervical-preparation, co-intervention, suction/Vabra, registry-only, or mixed-procedure records.",
      "reason": "Specifies groups for synthesis and links them to review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies were excluded from the primary analysis when they centered on hysteroscopy-guided biopsy, operative hysteroscopy, dilation and curettage, abortion procedures, suction curettage or Vabra sampling without separable blind EMB pain data, or inseparable combined gynecologic procedures, because those settings differ in instrumentation, duration, uterine distension, cervical manipulation, and pain mechanisms.",
      "reason": "Provides rationale for exclusion based on study characteristics."
    }
  ],
  "confidence": 90
}

